use rubydex::{
    config::Config,
    indexing::{index_files, index_source, IndexerBackend, LanguageId},
    listing,
    model::{declaration::Ancestor, graph::Graph},
    resolution::Resolver,
};

fn snapshot(graph: &Graph) -> Vec<String> {
    let mut rows = Vec::new();
    for (id, decl) in graph.declarations() {
        let ancestors = decl.as_namespace().map(|ns| ns.ancestors().iter().map(|a| {
            match a {
                Ancestor::Complete(id) => graph.declarations().get(id).unwrap().name().to_string(),
                Ancestor::Partial(_) => "<partial>".to_string(),
            }
        }).collect::<Vec<_>>());
        rows.push(format!("{} visibility={:?} ancestors={:?}", decl.name(), graph.visibility(id), ancestors));
    }
    for def in graph.definitions().values() {
        rows.push(format!("definition={def:?}"));
    }
    for reference in graph.constant_references().values() {
        rows.push(format!("constant_reference={reference:?}"));
    }
    for reference in graph.method_references().values() {
        rows.push(format!("method_reference={reference:?}"));
    }
    for diagnostic in graph.all_diagnostics() {
        rows.push(format!("diagnostic={diagnostic:?}"));
    }
    rows.sort();
    rows
}

fn main() {
    let args: Vec<_> = std::env::args().collect();
    let mut graph = Graph::new();
    if args[1] == "--corpus" {
        let path = std::path::Path::new(&args[2]);
        graph.load_config(&Config::load(path).unwrap());
        let (paths, errors) = listing::collect_file_paths(vec![args[2].clone()], &graph.excluded_patterns());
        assert!(errors.is_empty(), "{errors:?}");
        let errors = index_files(&mut graph, paths, IndexerBackend::RubyIndexer);
        assert!(errors.is_empty(), "{errors:?}");
        Resolver::new(&mut graph).resolve();
        for row in snapshot(&graph) { println!("{row}"); }
        return;
    }
    for path in &args[1..] {
        let source = std::fs::read_to_string(path).unwrap();
        let lang = if path.ends_with(".rbs") { LanguageId::Rbs } else { LanguageId::Ruby };
        index_source(&mut graph, format!("file://{path}").into(), &source, &lang);
    }
    Resolver::new(&mut graph).resolve();
    for row in snapshot(&graph) { println!("{row}"); }
    println!("diagnostics={:?}", graph.all_diagnostics());
    for path in &args[1..] {
        let source = std::fs::read_to_string(path).unwrap();
        let lang = if path.ends_with(".rbs") { LanguageId::Rbs } else { LanguageId::Ruby };
        let before = snapshot(&graph);
        index_source(&mut graph, format!("file://{path}").into(), &(source + "\n# trailing comment\n"), &lang);
        Resolver::new(&mut graph).resolve();
        println!("incremental_comment_semantics_equal={}", before == snapshot(&graph));
    }
}
